from datetime import date, timedelta


class LeaveTracker:
    def __init__(self, days_per_year: int = 26, holidays: list[date] | None = None) -> None:
        self.days_per_year = days_per_year
        self.holidays = set(holidays) if holidays else set()
        # For each employee and year, the number of leave days used.
        self._used: dict[str, dict[int, int]] = {}

    def _is_working_day(self, d: date) -> bool:
        # Monday=0 ... Sunday=6 -> weekends are 5 and 6
        if d.weekday() >= 5:
            return False
        if d in self.holidays:
            return False
        return True

    def _count_leave_days(self, start: date, end: date) -> int:
        total = 0
        current = start
        while current <= end:
            if self._is_working_day(current):
                total += 1
            current += timedelta(days=1)
        return total

    def request(self, employee: str, start: date, end: date, today: date) -> int:
        if end < start:
            raise ValueError("End date must not be before start date.")
        if (start - today).days < 3:
            raise ValueError("Leave must be requested at least 3 days in advance.")

        used = self._count_leave_days(start, end)

        year = start.year
        emp_used = self._used.setdefault(employee, {})
        already = emp_used.get(year, 0)

        remaining = self.days_per_year - already
        if used > remaining:
            raise ValueError("Not enough leave days remaining for this year.")

        emp_used[year] = already + used
        return used

    def remaining(self, employee: str, year: int) -> int:
        used = self._used.get(employee, {}).get(year, 0)
        return self.days_per_year - used
